INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_APSYSTEMS', 'FORMATO_DATA', 'Indicare il formato della data da parsare nella lettura di un protocollo, se non indicato la stringa di default sarà "dd/MM/yyyy h.mm.ss"');
Insert into verticalizzazioniparametribase (MODULO,PARAMETRO,DESCRIZIONE) values ('COMPORTAMENTI_MERCATI','INS_CONCESSIONARI_PRESENTI','Se attivato contestualmente all''inserimento della giornata di mercato vengono inseriti in automatico come presenti i concessionari');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_PROTOINF', 'CODICI_ENDOPROC_SMISTAMENTI', 'Indicare, separati da virgola,i codici degli endoprocedimenti che serviranno per smistare le pratiche. La logica è quella che, nella tabella INVENTARIOPROCEDIMENTI (in Join con ISTANZEPROCEDIMENTI), esisterà un solo procedimento presente in questa lista (di questo parametro), a quel punto sarà quel procedimento che indicherà a quale modulo software fa riferimento quella determinata pratica.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('ALLINEAMENTO_ANAGRAFE_FORLIV', 'DATA_AGGIORNAMENTO_DA', 'Indicare da quale data deve essere effettuato l''aggiornamento, la data si riferisce al campo DATA_ULTIMA_VARIAZ della vista esposta nel parametro VIEW. Tale campo si riferisce quando è stata fatta l''ultima modifica dell''anagrafica, questo parametro va a filtrare proprio quella data. Il formato deve essere dd/MM/yyyy');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('ALLINEAMENTO_ANAGRAFE_FORLIV', 'DATA_AGGIORNAMENTO_A', 'Indicare a quale data deve essere effettuato l''aggiornamento, la data si riferisce al campo DATA_ULTIMA_VARIAZ della vista esposta nel parametro VIEW. Tale campo si riferisce quando è stata fatta l''ultima modifica dell''anagrafica, questo parametro va a filtrare proprio quella data. Il formato deve essere dd/MM/yyyy');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('ALLINEAMENTO_ANAGRAFE_FORLIV', 'NUM_GIORNI_AGGIORNAMENTO', 'Indicare su quanti giorni indietro (dalla data odierna) deve essere fatto l''aggiornamento in base alle ultime variazioni (campo DATA_ULTIMA_VARIAZ della vista indicata nel parametro VIEW). Non indicare, o indicare 0 se si vuole controllare solo la data odierna.');
